    25	public class CustomerListView extends VerticalLayout {
    26	
    27	    private final CustomerService customerService;
    28	    private final Grid<Customer> grid = new Grid<>(Customer.class, false);
    29	
    30	    public CustomerListView(CustomerService customerService) {
    31	        this.customerService = customerService;
    32	
    33	        setSizeFull();
    34	        add(new H2("Customers"), grid);
    35	
    36	        configureGrid();
    37	    }
    38	
    39	    private void configureGrid() {
    40	        grid.addColumn(Customer::firstName).setHeader("First name")
    41	                .setKey("firstName").setSortProperty("firstName");
    42	        grid.addColumn(Customer::lastName).setHeader("Last name")
    43	                .setKey("lastName").setSortProperty("lastName");
    44	        grid.addColumn(Customer::email).setHeader("Email")
    45	                .setKey("email").setSortProperty("email");
    46	        grid.addColumn(Customer::country).setHeader("Country")
    47	                .setKey("country").setSortProperty("country");
    48	        grid.addColumn(customer -> customer.status().name()).setHeader("Status")
    49	                .setKey("status").setSortProperty("status");
    50	        grid.setSizeFull();
    51	
    52	        grid.setItems(
    53	                query -> customerService
    54	                        .list(query.getOffset(), query.getLimit(), toSorts(query.getSortOrders()))
    55	                        .stream(),
    56	                query -> customerService.count());
    57	    }
    58	
    59	    private static List<CustomerSort> toSorts(List<QuerySortOrder> sortOrders) {
    60	        return sortOrders.stream()
    61	                .map(order -> new CustomerSort(
    62	                        order.getSorted(), order.getDirection() == SortDirection.ASCENDING))
    63	                .toList();
    64	    }
    65	}
