+package com.example.customers.domain;
+
+import java.text.Normalizer;
+import java.util.List;
+import java.util.Locale;
+import java.util.Set;
+import java.util.function.Predicate;
+import java.util.regex.Pattern;
+
+/**
+ * Which customers a query asks for: a piece of a name and a set of statuses.
+ *
+ * <p>The name is split on whitespace into terms, and every term must appear as a
+ * substring of the customer's first name or of the last name. Matching ignores
+ * case and accents. An empty name matches every customer.
+ *
+ * <p>An empty set of statuses matches every status; otherwise a customer must
+ * have one of the listed statuses.
+ *
+ * @param name     text to look for in customers' names, surrounding whitespace is
+ *                 not significant; {@code null} is treated as empty
+ * @param statuses the statuses to keep; {@code null} is treated as empty
+ */
+public record CustomerFilter(String name, Set<CustomerStatus> statuses) {
+
+    /** Matches every customer. */
+    public static final CustomerFilter ALL = new CustomerFilter("", Set.of());
+
+    private static final Pattern WHITESPACE = Pattern.compile("\\s+");
+    private static final Pattern COMBINING_MARKS = Pattern.compile("\\p{M}+");
+
+    public CustomerFilter {
+        name = (name == null) ? "" : name.strip();
+        statuses = (statuses == null) ? Set.of() : Set.copyOf(statuses);
+    }
+
+    /**
+     * Returns a test for this filter. The name terms are worked out here, once,
+     * rather than again for every customer.
+     */
+    public Predicate<Customer> toPredicate() {
+        List<String> terms = nameTerms(name);
+        return customer -> (statuses.isEmpty() || statuses.contains(customer.status()))
+                && matchesName(customer, terms);
+    }
+
+    private static List<String> nameTerms(String name) {
+        String folded = fold(name);
+        return folded.isEmpty() ? List.of() : List.of(WHITESPACE.split(folded));
+    }
+
+    private static boolean matchesName(Customer customer, List<String> terms) {
+        if (terms.isEmpty()) {
+            return true;
+        }
+        String first = fold(customer.firstName());
+        String last = fold(customer.lastName());
+        return terms.stream().allMatch(term -> first.contains(term) || last.contains(term));
+    }
+
+    /** Lower-cases and strips accents, so that "Mäkinen" and "makinen" compare equal. */
+    private static String fold(String text) {
+        String decomposed = Normalizer.normalize(text.toLowerCase(Locale.ROOT), Normalizer.Form.NFD);
+        return COMBINING_MARKS.matcher(decomposed).replaceAll("");
+    }
+}
