+package com.example.customers.domain;
+
+import static org.junit.jupiter.api.Assertions.assertEquals;
+import static org.junit.jupiter.api.Assertions.assertFalse;
+import static org.junit.jupiter.api.Assertions.assertTrue;
+
+import java.util.Set;
+
+import org.junit.jupiter.api.Test;
+
+class CustomerFilterTest {
+
+    private static final Customer ADA = new Customer(
+            1, "Ada", "Aaltonen", "ada@example.com", "Finland", CustomerStatus.ACTIVE);
+    private static final Customer JOSEPHINE = new Customer(
+            2, "Joséphine", "Mäkinen", "josephine@example.com", "France", CustomerStatus.CLOSED);
+
+    private static boolean matches(CustomerFilter filter, Customer customer) {
+        return filter.toPredicate().test(customer);
+    }
+
+    private static CustomerFilter name(String name) {
+        return new CustomerFilter(name, Set.of());
+    }
+
+    @Test
+    void blankNameMatchesEveryCustomer() {
+        assertTrue(matches(name(""), ADA));
+        assertTrue(matches(name("   "), JOSEPHINE));
+        assertTrue(matches(CustomerFilter.ALL, JOSEPHINE));
+    }
+
+    @Test
+    void everyTermMustAppearInTheFirstOrLastName() {
+        assertTrue(matches(name("ada aal"), ADA));
+        assertTrue(matches(name("aal ada"), ADA));
+        assertTrue(matches(name("  ada   aal  "), ADA));
+        assertFalse(matches(name("ada mäkinen"), ADA));
+        assertTrue(matches(name("joséphine mäkinen"), JOSEPHINE));
+    }
+
+    @Test
+    void termsAreMatchedAsSubstringsOfEitherName() {
+        assertFalse(matches(name("join"), JOSEPHINE));
+        assertTrue(matches(name("jose"), JOSEPHINE));
+        assertTrue(matches(name("kinen"), JOSEPHINE));
+    }
+
+    @Test
+    void caseIsIgnored() {
+        assertTrue(matches(name("MAKINEN"), JOSEPHINE));
+        assertTrue(matches(name("josÉphine"), JOSEPHINE));
+    }
+
+    @Test
+    void accentsAreIgnoredInBothDirections() {
+        // Unaccented query, accented name.
+        assertTrue(matches(name("makinen"), JOSEPHINE));
+        assertTrue(matches(name("josephine"), JOSEPHINE));
+        // Accented query, unaccented name.
+        assertTrue(matches(name("Aáltonen"), ADA));
+        assertTrue(matches(name("mäkinen"), JOSEPHINE));
+    }
+
+    @Test
+    void statusFilterKeepsOnlyTheChosenStatuses() {
+        CustomerFilter activeOnly = new CustomerFilter("", Set.of(CustomerStatus.ACTIVE));
+        assertTrue(matches(activeOnly, ADA));
+        assertFalse(matches(activeOnly, JOSEPHINE));
+
+        CustomerFilter emptySet = new CustomerFilter("", Set.of());
+        assertTrue(matches(emptySet, ADA));
+        assertTrue(matches(emptySet, JOSEPHINE));
+    }
+
+    @Test
+    void nameAndStatusMustBothMatch() {
+        CustomerFilter both = new CustomerFilter("makinen", Set.of(CustomerStatus.ACTIVE));
+        assertFalse(matches(both, JOSEPHINE));
+        assertFalse(matches(both, ADA));
+    }
+
+    @Test
+    void nullsMeanNoRestriction() {
+        CustomerFilter none = new CustomerFilter(null, null);
+        assertEquals("", none.name());
+        assertEquals(Set.of(), none.statuses());
+        assertTrue(matches(none, JOSEPHINE));
+    }
+}
